import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CDEKL17z.js";const o="/michi-chat/screenshots/admin-login.png",n="/michi-chat/screenshots/admin-dashboard.png",r="/michi-chat/screenshots/tenant-form.png",h="/michi-chat/screenshots/tenant-kb.png",l="/michi-chat/screenshots/tenant-keys.png",f=JSON.parse('{"title":"Set it up, step by step","description":"","frontmatter":{},"headers":[],"relativePath":"owner/setup.md","filePath":"owner/setup.md"}'),p={name:"owner/setup.md"};function c(u,e,d,g,m,b){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="set-it-up-step-by-step" tabindex="-1">Set it up, step by step <a class="header-anchor" href="#set-it-up-step-by-step" aria-label="Permalink to &quot;Set it up, step by step&quot;">​</a></h1><p>Fifteen minutes from login to a working assistant. (Someone technical installs the platform first - that&#39;s the <a href="./../guide/quickstart">Quickstart</a> - then everything below is yours.)</p><h2 id="_1-sign-in" tabindex="-1">1. Sign in <a class="header-anchor" href="#_1-sign-in" aria-label="Permalink to &quot;1. Sign in&quot;">​</a></h2><p>Open <code>/admin</code> and enter the operator password.</p><p><img src="'+o+'" alt="The admin sign-in"></p><h2 id="_2-create-your-business" tabindex="-1">2. Create your business <a class="header-anchor" href="#_2-create-your-business" aria-label="Permalink to &quot;2. Create your business&quot;">​</a></h2><p>The dashboard lists every business on the platform. Fill in <strong>New tenant</strong> at the bottom - a name and a short web-friendly ID (the &quot;slug&quot;, used in your chat address).</p><p><img src="'+n+'" alt="The dashboard with the tenant list and the New tenant form"></p><h2 id="_3-fill-in-the-profile" tabindex="-1">3. Fill in the profile <a class="header-anchor" href="#_3-fill-in-the-profile" aria-label="Permalink to &quot;3. Fill in the profile&quot;">​</a></h2><p>Click your business to open its settings page. Work top to bottom:</p><p><img src="'+r+'" alt="The tenant settings form"></p><ul><li><strong>Persona</strong> - describe who the assistant is, in plain words: your business name, location, what you sell, the tone to use (&quot;warm and brief&quot;, &quot;playful&quot;). This is its personality, not its knowledge - facts come next.</li><li><strong>Branding</strong> - the title, greeting, colors, your logo (paste an https image URL) and the suggested questions visitors see. The suggestions stay available during the conversation as a small arrowed carousel above the message box.</li><li><strong>Visitor notice</strong> - the text under the message box. Use it for three things: ask visitors not to share sensitive information, say what the assistant covers, and state that you never ask for payment in chat (and where payment actually happens). That last line is real protection against impersonation scams.</li><li><strong>Tools</strong> - switches for live abilities (like reading your current menu from your website). Turn on <strong>search_kb</strong> so the assistant can use the knowledge you add in the next step.</li><li><strong>Daily message cap</strong> - the safety valve. Once a day&#39;s messages hit this number, the assistant politely stops until midnight. This is what makes the bill predictable.</li><li><strong>Notifications</strong> - paste a Slack webhook and you get a Slack message whenever a new conversation starts, and once if the daily cap is reached.</li></ul><h2 id="_4-teach-it-your-facts" tabindex="-1">4. Teach it your facts <a class="header-anchor" href="#_4-teach-it-your-facts" aria-label="Permalink to &quot;4. Teach it your facts&quot;">​</a></h2><p>Open <strong>Knowledge base</strong>. Each document is a page of facts in your words - hours and location, frequently asked questions, policies. Use headings, keep one fact per section.</p><p><img src="'+h+'" alt="The knowledge base editor"></p><p>Click <strong>Save &amp; embed</strong> and the facts are searchable immediately. Rule of thumb: only write what you&#39;d happily say to a customer at the counter.</p><h2 id="_5-put-it-on-your-website" tabindex="-1">5. Put it on your website <a class="header-anchor" href="#_5-put-it-on-your-website" aria-label="Permalink to &quot;5. Put it on your website&quot;">​</a></h2><p><strong>Embed keys</strong> shows the key that identifies your business, and the tenant settings hold the <strong>Allowed origins</strong> - the list of websites permitted to embed your assistant.</p><p><img src="'+l+'" alt="The embed keys page"></p><p>Your web person takes it from here: <a href="./../guide/embedding">Embedding on a website</a> has the copy-paste snippet.</p><p>That&#39;s it. Ask the assistant something you just taught it - then read <a href="./day-to-day">Running it day to day</a>.</p>',21)])])}const _=t(p,[["render",c]]);export{f as __pageData,_ as default};
